// This code has been fully generated by an AI.

package insight

import (
	"fmt"
	"math"
	"strings"
)

func comma(format string, v float64) string {
	return strings.Replace(fmt.Sprintf(format, v), ".", ",", 1)
}

// Distribution assesses the intensity distribution of the last weeks.
type Distribution struct {
	Easy, Moderate, Hard float64 // shares of time in HR zones 1–2, 3, 4–5
	Monotony             float64 // mean / standard deviation of the daily load (7 days)
	Strain               float64 // weekly load × monotony
	ActiveDaysPerWeek    float64
	Statements           []string
}

// AssessDistribution evaluates hours per HR zone (index = zone 1–5; zone 0
// ignored), the daily loads of the last 7 days (oldest first) and the
// number of active days within weeks.
func AssessDistribution(zoneHours map[int]float64, last7 []float64, activeDays int, weeks int) Distribution {
	var d Distribution
	total := 0.0
	for z := 1; z <= 5; z++ {
		total += zoneHours[z]
	}
	if total > 0 {
		d.Easy = (zoneHours[1] + zoneHours[2]) / total
		d.Moderate = zoneHours[3] / total
		d.Hard = (zoneHours[4] + zoneHours[5]) / total
		pct := func(v float64) string { return fmt.Sprintf("%.0f %%", 100*v) }
		switch {
		case d.Moderate > 0.25:
			d.Statements = append(d.Statements, fmt.Sprintf("Viel mittlere Intensität (Z3 %s): lockere Einheiten lockerer, harte gezielter fahren.", pct(d.Moderate)))
		case d.Easy >= 0.75 && d.Moderate <= 0.15:
			d.Statements = append(d.Statements, fmt.Sprintf("Polarisierte Verteilung (%s locker, %s intensiv) – entspricht dem 80/20-Prinzip.", pct(d.Easy), pct(d.Hard)))
		default:
			d.Statements = append(d.Statements, fmt.Sprintf("%s locker, %s mittel, %s intensiv.", pct(d.Easy), pct(d.Moderate), pct(d.Hard)))
		}
		if d.Hard < 0.05 {
			d.Statements = append(d.Statements, "Kaum intensive Anteile – für Leistungsentwicklung gelegentlich harte Intervalle einplanen.")
		}
	}
	if len(last7) > 0 {
		var sum, sq float64
		for _, v := range last7 {
			sum += v
		}
		mean := sum / float64(len(last7))
		for _, v := range last7 {
			sq += (v - mean) * (v - mean)
		}
		sd := math.Sqrt(sq / float64(len(last7)))
		if sd > 0 {
			d.Monotony = mean / sd
			d.Strain = sum * d.Monotony
		}
		if d.Monotony > 2 {
			d.Statements = append(d.Statements, "Sehr gleichförmige Belastung (Monotonie "+comma("%.1f", d.Monotony)+") – bewusst leichte Tage oder Ruhetage einplanen.")
		}
	}
	if weeks > 0 {
		d.ActiveDaysPerWeek = float64(activeDays) / float64(weeks)
		if d.ActiveDaysPerWeek < 2 {
			d.Statements = append(d.Statements, "Im Schnitt "+comma("%.1f", d.ActiveDaysPerWeek)+" aktive Tage pro Woche – regelmäßigere Einheiten bringen mehr als seltene lange.")
		}
	}
	return d
}
